SELECT 'gongkao', '周期轮换', 'kp-eng-s-cycle', CAST($${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "周期轮换"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fffbeb", "borderColor": "#f59e0b", "icon": "💡"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "核心定义：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "捆绑周期法。把一轮（如甲1天乙1天）看作一个大整体。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "一、题型定义与识别"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "关键词：“甲做1天，乙做1天，交替进行”，或者“甲做2小时，乙做3小时，轮流施工”。"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "二、核心推导"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "千万不能用总工作量除以合作效率，因为他们是错开干的！必须打包。"}]}, {"type": "katexBlock", "attrs": {"content": "W_{周期} = P_A \\times T_A + P_B \\times T_B \\quad \\text{(每一轮产出的工作量)}"}}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "三、标准步骤"}]}, {"type": "text-diagram", "attrs": {"type": "mermaid", "content": "flowchart TD\nA[赋总量, 出效率] --> B[计算一个'完整周期'内完成的工程量 W周]\nB --> C[用 W总 ÷ W周 = N轮 ... 余数]\nC --> D[计算这 N 轮花费了多少天]\nD --> E[拿着剩下的余数, 按照题目规定的顺序(甲先还是乙先), 一天天去扣减]\nE --> F[得出剩余工作需要的天数, 相加得出总天数]"}}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "四、例题完整推导"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "【例题】", "marks": [{"type": "bold"}]}, {"type": "text", "text": " 甲需 4 天，乙需 6 天。按照 甲1天、乙1天 的顺序轮流做。需要几天？选项：A. 4.6  B. 4.8  C. 5  D. 5.2"}]}, {"type": "orderedList", "attrs": {"start": 1}, "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "赋总量：4 和 6 的公倍数 W = 12。P甲 = 3，P乙 = 2。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "打包一轮：一个周期是 2 天（甲1天+乙1天）。一周期干的活 = 3 + 2 = 5。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "求轮数：12 ÷ 5 = 2 轮 ... 余 2 个工作量。这两轮花费了 2 × 2 = 4 天。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "处理余数：剩下 2 个工作量。下一轮该甲上场。甲一天能干 3。所以甲只需要 2/3 天就能干完。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "汇总：总天数 = 4 天 + 2/3 天 ≈ 4.67 天。选 A 对应最接近。（考场精确选项可能带分数）"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "五、易错点纠偏"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fef2f2", "borderColor": "#ef4444", "icon": "⚠️"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "余数除以合作效率：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "算出余数 2 之后，千万不要用 2 ÷ (3+2) = 0.4 天！轮换工程里从来不存在“两人同时干”，余下的活必须按顺序一个人一个人去干。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "六、刷题建议"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "重点练习“最后一步余数的处理”。特别是遇到余数刚好够甲干完，或者甲干完还剩一点要乙接着干的复杂尾巴。"}]}]}$$ AS jsonb), NULL, '周期轮换的核心考点与实战推导。', category_node.id, CAST('["数量关系", "工程问题", "周期轮换"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_eng_s_cycle", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
FROM category_node ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, content_json = EXCLUDED.content_json, summary = EXCLUDED.summary, category_id = EXCLUDED.category_id, tags = EXCLUDED.tags, updated_time = NOW();
